BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH base AS MATERIALIZED(SELECT ts_code,name FROM raw_tushare.stock_basic WHERE ts_code !~ '^(200|900)' AND list_status IN('L','P') AND list_date<=DATE '2026-10-30' AND(delist_date IS NULL OR delist_date>DATE '2026-10-30')),m AS MATERIALIZED(SELECT DISTINCT i.trade_date,i.level,m.con_code FROM core_serving.dc_index i JOIN core_serving.dc_member m ON m.ts_code=i.ts_code AND m.trade_date=i.trade_date WHERE i.trade_date IN(DATE '2026-10-29',DATE '2026-10-30') AND i.idx_type='行业板块' AND i.level IN('东财一级行业','东财二级行业')),ds AS(SELECT DISTINCT trade_date,level FROM m),q AS(SELECT ds.trade_date,ds.level,count(*) eligible_codes,count(m.con_code) mapped_codes FROM ds CROSS JOIN base b LEFT JOIN m ON m.trade_date=ds.trade_date AND m.level=ds.level AND m.con_code=b.ts_code GROUP BY ds.trade_date,ds.level),missing AS(SELECT b.ts_code,b.name FROM base b WHERE NOT EXISTS(SELECT 1 FROM m WHERE m.trade_date=DATE '2026-10-30' AND m.level='东财一级行业' AND m.con_code=b.ts_code) ORDER BY b.ts_code LIMIT 20)
SELECT jsonb_build_object('section','latest_member_alignment','as_of',current_timestamp,'data',(SELECT jsonb_agg(to_jsonb(q) ORDER BY trade_date,level) FROM q),'latest_level1_missing_samples',(SELECT jsonb_agg(to_jsonb(missing)) FROM missing));
COMMIT;
